using System.Runtime.CompilerServices;using System.Text.Json;using System.Threading.Channels;using SvcSystems.AI.AgentClientProtocol.Serialization;using AcpClient = SvcSystems.AI.AgentClientProtocol.Client.Client;namespace SvcSystems.AI.AgentClientProtocol;/// <summary>An ACP conversation session.</summary>public sealed class Session{    private static readonly TimeSpan CancellationDrainTimeout = TimeSpan.FromSeconds(15);    private readonly AcpClient _client;    private readonly Channel<SessionEvent> _updates;    private readonly int _maximumBufferedUpdates;    private Exception? _updateBufferFailure;    private IReadOnlyList<string>? _promptSuggestions;    private readonly SemaphoreSlim _promptLock = new(1, 1);    internal Session(AcpClient client, string id, int maximumBufferedUpdates = 1024)    {        if (maximumBufferedUpdates <= 0) throw new ArgumentOutOfRangeException(nameof(maximumBufferedUpdates));        _client = client;        Id = id;        _maximumBufferedUpdates = maximumBufferedUpdates;        _updates = Channel.CreateBounded<SessionEvent>(new BoundedChannelOptions(maximumBufferedUpdates)        {            SingleReader = true,            SingleWriter = false,            FullMode = BoundedChannelFullMode.Wait,            AllowSynchronousContinuations = false        });    }    /// <summary>Agent-provided session id.</summary>    public string Id { get; }    /// <summary>The complete most recent session creation, load, or resume response.</summary>    public JsonElement? RawPayload { get; private set; }    /// <summary>The agent's initial or most recently reported mode state.</summary>    public SessionModeState? ModeState { get; private set; }    /// <summary>The agent's initial or most recently reported configuration options.</summary>    public IReadOnlyList<SessionConfigOption> ConfigOptions { get; private set; } = Array.Empty<SessionConfigOption>();    /// <summary>Latest suggested next prompts, or null when no suggestions have been reported.</summary>    public IReadOnlyList<string>? PromptSuggestions => Volatile.Read(ref _promptSuggestions);    /// <summary>Sends a text prompt and streams normalized ACP updates until the turn finishes.</summary>    public IAsyncEnumerable<SessionEvent> PromptAsync(string prompt, CancellationToken cancellationToken = default)    {        ArgumentNullException.ThrowIfNull(prompt);        return PromptAsync([new TextContent { Text = prompt }], cancellationToken);    }    /// <summary>Sends a text prompt with request-scoped extension metadata.</summary>    public IAsyncEnumerable<SessionEvent> PromptAsync(string prompt, CancellationToken cancellationToken, PromptOptions options)    {        ArgumentNullException.ThrowIfNull(prompt);        ArgumentNullException.ThrowIfNull(options);        return PromptCoreAsync([new TextContent { Text = prompt }], options, cancellationToken);    }    /// <summary>Sends typed prompt content and streams normalized ACP updates until the turn finishes.</summary>    public IAsyncEnumerable<SessionEvent> PromptAsync(        IReadOnlyList<ContentBlock> content,        CancellationToken cancellationToken = default) =>        PromptCoreAsync(content, null, cancellationToken);    /// <summary>Sends typed prompt content with request-scoped extension metadata.</summary>    public IAsyncEnumerable<SessionEvent> PromptAsync(        IReadOnlyList<ContentBlock> content, CancellationToken cancellationToken, PromptOptions options)    {        ArgumentNullException.ThrowIfNull(options);        return PromptCoreAsync(content, options, cancellationToken);    }    private async IAsyncEnumerable<SessionEvent> PromptCoreAsync(        IReadOnlyList<ContentBlock> content,        PromptOptions? options,        [EnumeratorCancellation] CancellationToken cancellationToken)    {        ArgumentNullException.ThrowIfNull(content);        await _promptLock.WaitAsync(cancellationToken).ConfigureAwait(false);        Task<PromptResponse>? promptTask = null;        using var promptRequestCancellation = new CancellationTokenSource();        var completed = false;        try        {            ThrowIfUpdateBufferFailed();            promptTask = _client.PromptAsync(Id, content, promptRequestCancellation.Token, options);            while (true)            {                cancellationToken.ThrowIfCancellationRequested();                var updateTask = _updates.Reader.WaitToReadAsync(cancellationToken).AsTask();                var finished = await Task.WhenAny(promptTask, updateTask).ConfigureAwait(false);                if (finished == updateTask)                {                    if (!await updateTask.ConfigureAwait(false)) break;                    while (_updates.Reader.TryRead(out var update)) yield return update;                    continue;                }                var promptResult = await promptTask.ConfigureAwait(false);                while (_updates.Reader.TryRead(out var update)) yield return update;                ThrowIfUpdateBufferFailed();                completed = true;                yield return new Completed(promptResult);                break;            }        }        finally        {            if (!completed && promptTask is { IsCompleted: false })            {                try { await _client.CancelSessionAsync(Id, CancellationToken.None).ConfigureAwait(false); }                catch { /* the connection may already be closing */ }                var drained = await Task.WhenAny(promptTask, Task.Delay(CancellationDrainTimeout)).ConfigureAwait(false);                if (drained != promptTask)                {                    promptRequestCancellation.Cancel();                }                else                {                    try { await promptTask.ConfigureAwait(false); }                    catch { /* preserve cancellation or consumer-disposal as the primary outcome */ }                }            }            _promptLock.Release();        }    }    /// <summary>Cancels the active prompt turn, if any.</summary>    public Task CancelAsync(CancellationToken cancellationToken = default) =>        _client.CancelSessionAsync(Id, cancellationToken);    /// <summary>Changes the session's current operating mode.</summary>    public Task SetModeAsync(string modeId, CancellationToken cancellationToken = default) =>        _client.SetSessionModeAsync(Id, modeId, cancellationToken);    /// <summary>Sets a string-valued session configuration option.</summary>    public async Task<IReadOnlyList<SessionConfigOption>> SetConfigOptionAsync(string configId, string valueId, CancellationToken cancellationToken = default)    {        var options = await _client.SetSessionConfigOptionAsync(Id, configId, new SetSessionConfigOptionRequestCase1 { Value = valueId }, cancellationToken).ConfigureAwait(false);        ConfigOptions = options;        return options;    }    /// <summary>Sets a boolean-valued session configuration option.</summary>    public async Task<IReadOnlyList<SessionConfigOption>> SetConfigOptionAsync(string configId, bool value, CancellationToken cancellationToken = default)    {        var options = await _client.SetSessionConfigOptionAsync(Id, configId, new SetSessionConfigOptionRequestCase0 { Value = value }, cancellationToken).ConfigureAwait(false);        ConfigOptions = options;        return options;    }    internal bool Publish(SessionUpdate update)    {        if (Volatile.Read(ref _updateBufferFailure) is not null) return false;        switch (update.Value)        {            case SessionInfoUpdate sessionInfo                when WireJson.ReadPromptSuggestions(sessionInfo.Meta) is { } suggestions:                Volatile.Write(ref _promptSuggestions, suggestions);                break;            case CurrentModeUpdate mode when ModeState is { } state:                ModeState = new SessionModeState                {                    CurrentModeId = mode.CurrentModeId,                    AvailableModes = state.AvailableModes,                    Meta = state.Meta,                    ExtensionData = state.ExtensionData                };                break;            case CurrentModeUpdate mode:                ModeState = new SessionModeState { CurrentModeId = mode.CurrentModeId, AvailableModes = [] };                break;            case ConfigOptionUpdate config:                ConfigOptions = config.ConfigOptions;                break;        }        if (_updates.Writer.TryWrite(new SessionUpdateEvent(update))) return true;        var failure = new ProtocolException(            $"Session '{Id}' produced more than {_maximumBufferedUpdates} unread updates; its update stream is no longer usable.");        if (Interlocked.CompareExchange(ref _updateBufferFailure, failure, null) is null)        {            _updates.Writer.TryComplete(failure);        }        return false;    }    private void ThrowIfUpdateBufferFailed()    {        if (Volatile.Read(ref _updateBufferFailure) is { } failure)        {            throw new ProtocolException($"Session '{Id}' update buffering failed.", failure);        }    }    internal void SetInitialState(SessionModeState? modeState, IReadOnlyList<SessionConfigOption>? configOptions, JsonElement rawPayload)    {        if (modeState is not null) ModeState = modeState;        if (configOptions is not null) ConfigOptions = configOptions;        RawPayload = rawPayload.Clone();    }}